(() => {
  const btn=document.querySelector('#readBtn'),host=document.querySelector('#interactiveResult'),result=document.querySelector('#resultCard');if(!btn||!host||!result)return;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const names=['命宮','兄弟','夫妻','子女','財帛','疾厄','遷移','僕役','官祿','田宅','福德','父母'];
  const explain={紫微:'主導、整合資源及承擔責任。',貪狼:'探索、人際、慾望及多才；避免分心。',天機:'思考、變通及策劃；避免反覆。',太陰:'感受、照顧及安全感；留意情緒內收。',文昌:'學習、文書及邏輯表達。',文曲:'審美、技巧及情感表達。',天府:'資源管理、穩定及整合。',天鉞:'引薦及資源，維持專業信任。',太陽:'公開性、付出及領導；留意過勞。',天魁:'提攜及機會，主動展示能力。',武曲:'執行、財務及結果導向。',破軍:'改革、拆舊立新；先計算代價。',祿存:'資源累積及穩定。',天同:'和氣及調節壓力；避免拖延。',鈴星:'焦慮及突然變化；先穩住節奏。',地空:'落空及想像；用證據驗證。',天馬:'移動、轉換及外部機會。',陀羅:'拖延及暗阻；預留時間。',地劫:'損耗及資源破口。',廉貞:'界線、原則及創意。',七殺:'突破、決斷及高壓處理。',火星:'突發及急進；控制衝動。',天相:'協調、公平及制度支援。',左輔:'協作及助力。',天梁:'保護、原則及解難。',巨門:'語言、質疑及研究；留意口舌。'};
  btn.addEventListener('click',()=>setTimeout(()=>{if(document.querySelector('.method.active')?.dataset.name!=='紫微斗數'||!host.hidden&&host.querySelector('.star-chip'))return;const actual=window.__ziweiDisplayPalaces||[];const byName=new Map(actual.map(p=>[p.name,p.stars]));const stars=Object.fromEntries(names.map(n=>[n,[...(byName.get(n)||[])]]));host.hidden=false;result.classList.add('visual-mode');host.innerHTML=`<div class="chart-intro"><span>互動命盤</span><strong>12 宮 × 主星、輔星及雜曜；先揀宮，再點星</strong></div><div class="ziwei-board">${names.map((n,i)=>`<button class="palace-card ${i===0?'is-selected':''}" data-index="${i}"><small>${n}${n.endsWith('宮')?'':'宮'}</small><strong>${stars[n].slice(0,3).join('、')}</strong><span>${stars[n].length} 粒星 · 點擊解釋</span></button>`).join('')}</div><div class="palace-detail" id="emergencyPalaceDetail"></div><div class="term-drawer" id="emergencyTermDrawer" hidden></div>`;const detail=host.querySelector('#emergencyPalaceDetail'),drawer=host.querySelector('#emergencyTermDrawer'),render=i=>{const n=names[i];detail.innerHTML=`<p class="eyebrow">PALACE ${String(i+1).padStart(2,'0')}</p><h4>${n}</h4><p>${n==='命宮'?'代表本人性格、外在表現、人生主軸及面對事情的方式。':'先看宮位主題，再看星曜如何在此生活領域表現。'}</p><div class="star-list"><b>星曜（${stars[n].length}）</b><div>${stars[n].map(s=>`<button class="star-chip" data-star="${s}">${s}</button>`).join('')}</div></div><div class="star-explain-list">${stars[n].map(s=>`<div class="star-explain"><b>${s}</b><span>${explain[s]||'要連同宮位及流限判讀。'}</span></div>`).join('')}</div>`;host.querySelectorAll('.palace-card').forEach((c,j)=>c.classList.toggle('is-selected',j===i));detail.querySelectorAll('.star-chip').forEach(c=>c.onclick=()=>{drawer.hidden=false;drawer.innerHTML=`<button class="term-close">×</button><b>${c.dataset.star}</b><p>${explain[c.dataset.star]||'星曜要配合宮位解讀。'} 再核對亮度、會照及流年，最後落實到現實行動。</p>`;drawer.querySelector('button').onclick=()=>drawer.hidden=true;});};host.querySelectorAll('.palace-card').forEach((c,i)=>c.onclick=()=>render(i));render(0);},500));
})();
